    qdrant::{
        vectors_config::Config as VectorsConfigEnum, Condition, CreateCollectionBuilder, Distance,
        Filter, PointStruct, SearchPointsBuilder, UpsertPointsBuilder, VectorParamsBuilder,
        VectorsConfig,
    },
    Payload, Qdrant,
};
