            user_id: Some("u1".into()),
            conversation_id: Some("c1".into()),
            actor_id: "bot".into(),
            op_kind: OpKind::StateMutation,
            autonomous: false,
            confidence: None,
            plugin_id: Some("user-profile".into()),
            field: Some("email".into()),
            is_write: true,
            constraint_failed: false,
            memory_ref: None,
