//! Code-Context MCP Tools
//!
//! Coding-aware retrieval and indexing surfaces backed by the [`RagPipeline`]
//! (Voyage embeddings + Qdrant) and the [`ContextAwarenessEngine`]. These are
//! the tools an external coding client (Droid, Cursor, Codex) calls to pull
//! repository context.
//!
//! Tools:
//! - `code_search`  — filtered semantic search over indexed repos.
//!   subid: `obs.service.code-rag.search@v1`
//! - `code_context` — session-aware fused retrieval + awareness signals.
//!   subid: `exp.service.code-context.render@v1`
//! - `code_index`   — live indexing of a source file / repomix entry.
//!   subid: `src.software.workspace.index@v1`

use crate::context_awareness::{ActivityType, ContextAwarenessEngine};
use crate::rag_pipeline::{CodeFilter, RagPipeline, RagResult};
use anyhow::Result;
use async_trait::async_trait;
use op_mcp::tool_registry::{BoxedTool, Tool, ToolRegistry};
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::path::PathBuf;
use std::sync::Arc;

/// Register all code-context tools against the shared registry.
/// Returns the number of tools registered.
pub async fn register_code_tools(
    registry: &ToolRegistry,
    rag: Arc<RagPipeline>,
    engine: Arc<ContextAwarenessEngine>,
    collection: String,
) -> Result<usize> {
    registry
        .register(Arc::new(CodeSearchTool {
            rag: rag.clone(),
            collection: collection.clone(),
        }) as BoxedTool)
        .await?;
    registry
        .register(Arc::new(CodeContextTool {
            rag: rag.clone(),
            engine,
            collection: collection.clone(),
        }) as BoxedTool)
        .await?;
    registry
        .register(Arc::new(CodeIndexTool { rag, collection }) as BoxedTool)
        .await?;
    Ok(3)
}

// ─── code_search ────────────────────────────────────────────────────────────

pub struct CodeSearchTool {
    rag: Arc<RagPipeline>,
    collection: String,
}

#[async_trait]
impl Tool for CodeSearchTool {
    fn name(&self) -> &str {
        "code_search"
    }

    fn description(&self) -> &str {
        "Semantic code search over indexed repositories. Filter by repo, language, file_type, \
         path substring, or symbol. Returns ranked code chunks with symbols, imports, and line spans."
    }

    fn category(&self) -> &str {
        "code"
    }

    fn tags(&self) -> Vec<String> {
        vec![
            "code".into(),
            "search".into(),
            "rag".into(),
            "subid:obs.service.code-rag.search@v1".into(),
        ]
    }

    fn input_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "query": { "type": "string", "description": "Natural-language or code query" },
                "repo": { "type": "string", "description": "Restrict to a repo name" },
                "language": { "type": "string", "description": "Restrict to a language (e.g. rust, typescript)" },
                "file_type": { "type": "string", "enum": ["source", "test", "config", "docs", "build", "other"] },
                "path_contains": { "type": "string", "description": "Only files whose path contains this substring" },
                "symbol_contains": { "type": "string", "description": "Only chunks whose symbols/path contain this substring" },
                "exclude_tests": { "type": "boolean", "description": "Drop test files from results (default false)" },
                "fused": { "type": "boolean", "description": "Fuse semantic+lexical scoring and dedup to one chunk per file (default true)" },
                "limit": { "type": "integer", "description": "Max results (default 8)" }
            },
            "required": ["query"]
        })
    }

    async fn execute(&self, input: Value) -> Result<Value> {
        let query = input["query"]
            .as_str()
            .ok_or_else(|| anyhow::anyhow!("missing query"))?;
        let limit = input["limit"].as_u64().unwrap_or(8).clamp(1, 50);
        let filter = filter_from(&input, false);

        let results = if input["fused"].as_bool().unwrap_or(true) {
            self.rag
                .query_fused(&self.collection, query, limit, &filter)
                .await?
        } else {
            self.rag
                .query_filtered(&self.collection, query, limit, &filter)
                .await?
        };

        Ok(json!({
            "count": results.len(),
            "collection": self.collection,
            "results": results_to_simd(&results),
        }))
    }
}

// ─── code_context ───────────────────────────────────────────────────────────

pub struct CodeContextTool {
    rag: Arc<RagPipeline>,
    engine: Arc<ContextAwarenessEngine>,
    collection: String,
}

#[async_trait]
impl Tool for CodeContextTool {
    fn name(&self) -> &str {
        "code_context"
    }

    fn description(&self) -> &str {
        "Session-aware coding context. Records the current activity (query, edit, build_error, \
         test_failure, etc.) into the awareness engine, runs fused retrieval, and returns relevant \
         code plus session signals (stuck, recent errors, topics)."
    }

    fn category(&self) -> &str {
        "code"
    }

    fn tags(&self) -> Vec<String> {
        vec![
            "code".into(),
            "context".into(),
            "session".into(),
            "subid:exp.service.code-context.render@v1".into(),
        ]
    }

    fn input_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "query": { "type": "string", "description": "Current query / what the agent is working on" },
                "session_id": { "type": "string", "description": "Session identifier (default 'default')" },
                "activity_type": {
                    "type": "string",
                    "enum": [
                        "tool_call", "query", "context_switch", "error", "idle", "return_from_idle",
                        "file_opened", "edit_applied", "build_error", "test_failure", "diff_viewed", "symbol_navigated"
                    ],
                    "description": "Kind of activity being recorded (default 'query')"
                },
                "repo": { "type": "string", "description": "Restrict retrieval to a repo" },
                "language": { "type": "string", "description": "Restrict retrieval to a language" },
                "exclude_tests": { "type": "boolean", "description": "Drop test files from results (default false)" },
                "limit": { "type": "integer", "description": "Max results (default 6)" }
            },
            "required": ["query"]
        })
    }

    async fn execute(&self, input: Value) -> Result<Value> {
        let query = input["query"]
            .as_str()
            .ok_or_else(|| anyhow::anyhow!("missing query"))?;
        let session_id = input["session_id"].as_str().unwrap_or("default");
        let activity_type =
            ActivityType::parse(input["activity_type"].as_str().unwrap_or("query"));
        let limit = input["limit"].as_u64().unwrap_or(6).clamp(1, 50);

        // Record the activity so stuck/error/topic detection stays current.
        self.engine
            .record_activity(
                session_id,
                activity_type,
                query.to_string(),
                serde_json::json!({ "source": "code_context" }),
            )
            .await;

        let filter = filter_from(&input, false);
        let results = self
            .rag
            .query_fused(&self.collection, query, limit, &filter)
            .await?;

        let signals = self
            .engine
            .get_session_signals(session_id)
            .await
            .unwrap_or_else(|| serde_json::json!({ "session_id": session_id }));

        Ok(json!({
            "count": results.len(),
            "session_id": session_id,
            "signals": serde_to_simd(&signals),
            "results": results_to_simd(&results),
        }))
    }
}

// ─── code_index ─────────────────────────────────────────────────────────────

pub struct CodeIndexTool {
    rag: Arc<RagPipeline>,
    collection: String,
}

#[async_trait]
impl Tool for CodeIndexTool {
    fn name(&self) -> &str {
        "code_index"
    }

    fn description(&self) -> &str {
        "Index code into the semantic store. mode='source' indexes a single in-memory file \
         (repo, file_path, content) for live workspace updates; mode='repomix_zip' ingests an \
         entry from a repomix zip (zip_path, entry)."
    }

    fn category(&self) -> &str {
        "code"
    }

    fn tags(&self) -> Vec<String> {
        vec![
            "code".into(),
            "index".into(),
            "ingest".into(),
            "subid:src.software.workspace.index@v1".into(),
        ]
    }

    fn input_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "mode": { "type": "string", "enum": ["source", "repomix_zip"], "description": "Indexing mode (default 'source')" },
                "repo": { "type": "string", "description": "Repo name (source mode)" },
                "file_path": { "type": "string", "description": "File path within the repo (source mode)" },
                "content": { "type": "string", "description": "Raw file content (source mode)" },
                "zip_path": { "type": "string", "description": "Path to repomix zip (repomix_zip mode)" },
                "entry": { "type": "string", "description": "Entry name within the zip (repomix_zip mode)" },
                "collection": { "type": "string", "description": "Override target collection" }
            },
            "required": []
        })
    }

    async fn execute(&self, input: Value) -> Result<Value> {
        let collection = input["collection"].as_str().unwrap_or(&self.collection);
        let mode = input["mode"].as_str().unwrap_or("source");

        let stats = match mode {
            "source" => {
                let repo = input["repo"]
                    .as_str()
                    .ok_or_else(|| anyhow::anyhow!("source mode requires 'repo'"))?;
                let file_path = input["file_path"]
                    .as_str()
                    .ok_or_else(|| anyhow::anyhow!("source mode requires 'file_path'"))?;
                let content = input["content"]
                    .as_str()
                    .ok_or_else(|| anyhow::anyhow!("source mode requires 'content'"))?;
                self.rag
                    .ingest_source_text(repo, file_path, content, collection)
                    .await?
            }
            "repomix_zip" => {
                let zip_path = input["zip_path"]
                    .as_str()
                    .ok_or_else(|| anyhow::anyhow!("repomix_zip mode requires 'zip_path'"))?;
                let entry = input["entry"]
                    .as_str()
                    .ok_or_else(|| anyhow::anyhow!("repomix_zip mode requires 'entry'"))?;
                self.rag
                    .ingest_repomix_entry(&PathBuf::from(zip_path), entry, collection)
                    .await?
            }
            other => return Err(anyhow::anyhow!("unknown mode: {other}")),
        };

        Ok(json!({
            "ok": true,
            "mode": mode,
            "collection": collection,
            "files_parsed": stats.files_parsed as u64,
            "chunks_created": stats.chunks_created as u64,
            "chunks_upserted": stats.chunks_upserted as u64,
            "chunks_skipped": stats.chunks_skipped as u64,
            "errors": stats.errors as u64,
        }))
    }
}

// ─── helpers ──────────────────────────────────────────────────────────────────

fn filter_from(input: &Value, default_exclude_tests: bool) -> CodeFilter {
    CodeFilter {
        repo: input["repo"].as_str().map(String::from),
        language: input["language"].as_str().map(String::from),
        file_type: input["file_type"].as_str().map(String::from),
        path_contains: input["path_contains"].as_str().map(String::from),
        symbol_contains: input["symbol_contains"].as_str().map(String::from),
        exclude_tests: input["exclude_tests"]
            .as_bool()
            .unwrap_or(default_exclude_tests),
    }
}

fn results_to_simd(results: &[RagResult]) -> Value {
    let serde_val = serde_json::to_value(results).unwrap_or(serde_json::Value::Null);
    serde_to_simd(&serde_val)
}

fn serde_to_simd(v: &serde_json::Value) -> Value {
    let s = serde_json::to_string(v).unwrap_or_default();
    let mut buf = s.into_bytes();
    simd_json::from_slice(&mut buf).unwrap_or(Value::Static(simd_json::StaticNode::Null))
}

